/**
 * Conformance assertions that the *matching* path deliberately fails.
 *
 * The corpora were generated by the real package managers, so they encode
 * native dpkg and rpm ordering. `compare(..., { strict: true })` reproduces
 * that ordering exactly — all 71,629 assertions pass, with no exclusions.
 *
 * The matcher does not call it that way. It compares an advisory's bound
 * against a version the scanner read off a running container, and the two are
 * written to different levels of detail, so `dpkg.ts` and `rpm.ts` apply two
 * leniencies (documented at length in those files):
 *
 *  - a one-sided epoch is ignored rather than read as zero;
 *  - a one-sided release/revision is ignored rather than read as absent.
 *
 * Every assertion below is one where a leniency changes the answer. There are
 * 17 of them out of 71,629, and every one is a pair where one side states a
 * field the other omits — exactly the shape the leniencies exist for. None is
 * a bug we have not got round to.
 *
 * The harness asserts the failing set is *equal* to this list, so an exclusion
 * that becomes stale fails the build just as loudly as a new regression.
 */

export interface Exclusion {
    file: string;
    /** The assertion text, verbatim from the corpus. */
    assertion: string;
    reason: string;
}

const ONE_SIDED_EPOCH =
    "one side declares an epoch, the other omits it — matching drops the epoch rather than assuming zero";
const ONE_SIDED_RELEASE =
    "one side declares a release/revision, the other omits it — matching treats the omission as 'any release'";

export const CONFORMANCE_EXCLUSIONS: readonly Exclusion[] = [
    // ===== dpkg =====
    {
        file: "debian-versions-generated.txt",
        assertion: "1.0.rc15-2etch4 < 1:1.0.15-2.3",
        reason: ONE_SIDED_EPOCH,
    },
    {
        file: "debian-versions-generated.txt",
        assertion: "0.94.4-1.1 < 1:0.94.3~git20160113.dbc9ec6+dfsg-1",
        reason: ONE_SIDED_EPOCH,
    },
    {
        file: "debian-versions-generated.txt",
        assertion: "2020.07.12 < 1:9+2020.12.04",
        reason: ONE_SIDED_EPOCH,
    },
    {
        file: "debian-versions-generated.txt",
        assertion:
            "0.0~hg190-1+deb8u1 < 1:0.0~git20170407.0.55a552f+REALLY.0.0~git20161012.0.5f31782-1",
        reason: ONE_SIDED_EPOCH,
    },
    {
        file: "debian-versions-generated.txt",
        assertion: "0.cvs20060823-8 < 4:0.5.2-6",
        reason: ONE_SIDED_EPOCH,
    },
    {
        file: "debian-versions-generated.txt",
        assertion: "2014.1.3-7 < 3:14.0.2-3",
        reason: ONE_SIDED_EPOCH,
    },
    {
        file: "debian-versions-generated.txt",
        assertion: "19981008-0.1 < 2:1.0.0-0.woody.1",
        reason: ONE_SIDED_EPOCH,
    },
    {
        file: "debian-versions-generated.txt",
        assertion: "1.1.0+pre-3 < 1:1.1.0-1",
        reason: ONE_SIDED_EPOCH,
    },
    {
        file: "debian-versions-generated.txt",
        assertion: "2.20-8+etch2 < 1:2.2.0-4",
        reason: ONE_SIDED_EPOCH,
    },
    {
        file: "debian-versions-generated.txt",
        assertion: "20020409-1woody1 < 1:0.6.1-4",
        reason: ONE_SIDED_EPOCH,
    },
    {
        file: "debian-versions-generated.txt",
        assertion: "3.3.3 < 3.3.3-squeeze1",
        reason: ONE_SIDED_RELEASE,
    },

    // ===== rpm =====
    { file: "redhat-versions.txt", assertion: "3 < 1:2", reason: ONE_SIDED_EPOCH },
    { file: "redhat-versions.txt", assertion: "13 < 14:2", reason: ONE_SIDED_EPOCH },
    { file: "redhat-versions.txt", assertion: "1 < 1-1", reason: ONE_SIDED_RELEASE },
    { file: "redhat-versions.txt", assertion: "1 < 1-0", reason: ONE_SIDED_RELEASE },
    // Present twice in the corpus (lines 113 and 136); both occurrences diverge.
    { file: "redhat-versions.txt", assertion: "1 < 1-", reason: ONE_SIDED_RELEASE },
];

/** Excluded assertion texts for one corpus file. */
export function exclusionsFor(file: string): Set<string> {
    return new Set(
        CONFORMANCE_EXCLUSIONS.filter((e) => e.file === file).map((e) => e.assertion)
    );
}
